import json, sys, re

raw = json.load(sys.stdin)
result = json.loads(raw['result'])
experiments = result['data']['experiments']

# Collect all pi05 seed43 experiments
pi05_seed43 = {}
for name, exp in experiments.items():
    if 'pi05' in name and ('seed43' in name):
        pi05_seed43[name] = exp.get('status', 'UNKNOWN')

# Strict k-value extraction from experiment name
def extract_k(name):
    # Match patterns like k03, k05, k07, k085, k09, k0925, k095
    m = re.search(r'_k(\d+)_', name)
    if m:
        k_str = m.group(1)
        # Map to actual k value
        mapping = {'03':'0.3', '05':'0.5', '07':'0.7', '085':'0.85', 
                   '09':'0.9', '0925':'0.925', '095':'0.95'}
        return mapping.get(k_str, k_str)
    return None

def extract_mode(name):
    if 'l2norm' in name: return 'l2norm'
    if 'random' in name: return 'random'
    return None

def extract_suite(name):
    if 'object' in name: return 'object'
    if 'spatial' in name: return 'spatial'
    return None

k_values = ['0.3', '0.5', '0.7', '0.85', '0.9', '0.925', '0.95']
modes = ['l2norm', 'random']
suites = ['object', 'spatial']

# Build lookup: (suite, mode, k) -> (best_status, name)
lookup = {}
for name, status in pi05_seed43.items():
    k = extract_k(name)
    mode = extract_mode(name)
    suite = extract_suite(name)
    if k and mode and suite:
        key = (suite, mode, k)
        # Prefer DONE > RUNNING > others
        priority = {'DONE': 3, 'RUNNING': 2, 'PREPARING': 1}
        existing = lookup.get(key)
        if not existing or priority.get(status, 0) > priority.get(existing[0], 0):
            lookup[key] = (status, name)

missing_obj = []
missing_spa = []

for suite in suites:
    print(f'--- {suite} seed43 ---')
    for k in k_values:
        for mode in modes:
            key = (suite, mode, k)
            if key in lookup:
                status, name = lookup[key]
                marker = '✓' if status == 'DONE' else ('⏳' if status == 'RUNNING' else '?')
                print(f'  {marker} {mode:8s} k={k:<6} → {status:12s} ({name})')
            else:
                print(f'  ✗ {mode:8s} k={k:<6} → MISSING')
                if suite == 'object':
                    missing_obj.append((mode, k))
                else:
                    missing_spa.append((mode, k))
    print()

print('=== MISSING Object seed43 ===')
for mode, k in missing_obj:
    print(f'  {mode} k={k}')
print('=== MISSING Spatial seed43 ===')
for mode, k in missing_spa:
    print(f'  {mode} k={k}')

# Also check: are the RUNNING ones actually running somewhere?
print('\n=== RUNNING experiments (need to verify if actually alive) ===')
for key, (status, name) in sorted(lookup.items()):
    if status == 'RUNNING':
        print(f'  {name}')
